module freq_div (
    input CLK_in, RST,
    output CLK_50, CLK_10, CLK_1
);
// TODO: Please add your solution here
reg [0:0] cnt_50;
always @(posedge CLK_in or posedge RST) begin
    if(RST) begin
        cnt_50 <= 1'b0;
    end else begin
        cnt_50 <= ~cnt_50;
    end
end
reg [3:0] cnt_10;
always @(posedge CLK_in or posedge RST) begin
    if(RST) begin
        cnt_10 <= 4'd0;
    end else if(cnt_10 == 4'd4) begin
        cnt_10 <= 4'd0;
    end else begin
        cnt_10 <= cnt_10 + 1;
    end
end
reg [6:0] cnt_100;
always @(posedge CLK_in or posedge RST) begin
    if(RST) begin
        cnt_100 <= 7'd0;
    end else if(cnt_100 == 7'd49) begin
        cnt_100 <= 7'd0;
    end else begin
        cnt_100 <= cnt_100 + 1;
    end
end
assign CLK_50 = cnt_50;
assign CLK_10 = cnt_10[3];
assign CLK_1 = cnt_100[6];
endmodule
